(1906035, 262984, 37961, '<td valign="top">Blue Ribbon. 10.</td>', 'Blue Ribbon. 10.', '2005-11-30 00:31:50.000000', NULL, 1),
(1906093, 263662, 26313, '<td valign="top">I''d like to see more of the work piece and machines here (ie not cropped quite as close).</td>', 'I''d like to see more of the work piece and machines here (ie not cropped quite as close).', '2005-11-30 00:40:55.000000', NULL, 1),
(1906107, 262394, 47597, '<td valign="top">This is beautiful. The silhouettes of the machinery are great. I don''t mind that the sky is all white, because it focuses my attention on the machines.</td>', 'This is beautiful. The silhouettes of the machinery are great. I don''t mind that the sky is all white, because it focuses my attention on the machines.', '2005-11-30 00:42:50.000000', NULL, 1),
(1906113, 263493, 47597, '<td valign="top">It gives the impression of not being horizontal. The main focus is on the chimneys, but I wish I could see some detail of the large building at the bottom right. It''s all black for me. The sepia really makes it look dirty and industrial.</td>', 'It gives the impression of not being horizontal. The main focus is on the chimneys, but I wish I could see some detail of the large building at the bottom right. It''s all black for me. The sepia really makes it look dirty and industrial.', '2005-11-30 00:44:22.000000', NULL, 1),
(1906121, 262005, 47597, '<td valign="top">I like the reflection, but am put off by the blurry lights on the trees. I''d prefer to see the whole of the chimney.</td>', 'I like the reflection, but am put off by the blurry lights on the trees. I''d prefer to see the whole of the chimney.', '2005-11-30 00:45:48.000000', NULL, 1),
(1906130, 262318, 47597, '<td valign="top">Beautiful colours. Beutiful effluent! Most of the pics are BW in this challenge, because it''s hard to get an interesting colour pic of industry, but you''ve pulled it off.</td>', 'Beautiful colours. Beutiful effluent! Most of the pics are BW in this challenge, because it''s hard to get an interesting colour pic of industry, but you''ve pulled it off.', '2005-11-30 00:47:12.000000', NULL, 1),
(1906136, 263236, 47597, '<td valign="top">It''s chunky. It''s industrial. But the pic has no "wow" for me.</td>', 'It''s chunky. It''s industrial. But the pic has no "wow" for me.', '2005-11-30 00:48:10.000000', NULL, 1),
(1906153, 263712, 47597, '<td valign="top">I find that too much of the pic is taken up by the black sky.</td>', 'I find that too much of the pic is taken up by the black sky.', '2005-11-30 00:49:42.000000', NULL, 1),
(1906156, 263365, 47597, '<td valign="top">It''s too dark for me to make out much.</td>', 'It''s too dark for me to make out much.', '2005-11-30 00:50:28.000000', NULL, 1),
(1906162, 263532, 14212, '<td valign="top">love the color. great photo. 10</td>', 'love the color. great photo. 10', '2005-11-30 00:51:15.000000', NULL, 1),
