(1907180, 262355, 36722, '<td valign="top">too much off topic.</td>', 'too much off topic.', '2005-11-30 10:02:47.000000', NULL, 1),
(1907196, 263500, 43774, '<td valign="top">Photo looks oversharpened to me, it also looks like you took it from a  long distance and used a long zoom, therefore the quality isn''t as good as if you were closer. And even though this is an industrial challenge the wires are distrcting.</td>', 'Photo looks oversharpened to me, it also looks like you took it from a  long distance and used a long zoom, therefore the quality isn''t as good as if you were closer. And even though this is an industrial challenge the wires are distrcting.', '2005-11-30 10:10:11.000000', NULL, 1),
(1907199, 263188, 43774, '<td valign="top">Photo is very blurry with poor quality. If you took this at night you need to use a higher ISO and use a tripod to compensate for the long shutter speed.</td>', 'Photo is very blurry with poor quality. If you took this at night you need to use a higher ISO and use a tripod to compensate for the long shutter speed.', '2005-11-30 10:11:01.000000', NULL, 1),
