(1907309, 262788, 45857, '<td valign="top">Quite good industrial landscape, I like the unexpected blues, but the power lines are dubious, either added to the busy feeling or a distraction. I can''t decide.</td>', 'Quite good industrial landscape, I like the unexpected blues, but the power lines are dubious, either added to the busy feeling or a distraction. I can''t decide.', '2005-11-30 10:56:17.000000', NULL, 1),
(1907310, 262492, 739, '<td valign="top">The factory appears to be slightly out of focus.  Did you use a shutter release or a timer release?</td>', 'The factory appears to be slightly out of focus.  Did you use a shutter release or a timer release?', '2005-11-30 10:56:34.000000', NULL, 1),
(1907311, 263545, 34194, '<td valign="top">cool shot but not sure how it fits this challenge?</td>', 'cool shot but not sure how it fits this challenge?', '2005-11-30 10:56:39.000000', NULL, 1),
