INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1907730, 262220, 739, '<td valign="top">having the line focus in the foreground makes me think the "end of the line" is closest to me when I think you are referring to the factory as the end of the line.</td>', 'having the line focus in the foreground makes me think the "end of the line" is closest to me when I think you are referring to the factory as the end of the line.', '2005-11-30 13:43:35.000000', NULL, 1),
(1907734, 263471, 45857, '<td valign="top">I like the lines of the fence, but the image has a softness which doesn''t work well.</td>', 'I like the lines of the fence, but the image has a softness which doesn''t work well.', '2005-11-30 13:44:32.000000', NULL, 1),
(1907738, 263647, 24454, '<td valign="top">Very nicely done!  The composition on this one is very appealing, and I love the little splashes of color from the stairs.   Good luck with this one.  I LOVE it!!!  10</td>', 'Very nicely done!  The composition on this one is very appealing, and I love the little splashes of color from the stairs.   Good luck with this one.  I LOVE it!!!  10', '2005-11-30 13:47:11.000000', NULL, 1),
(1907739, 263231, 45857, '<td valign="top">I like the colors here, but the image has a ''watery'' impressionistic feel, which works well for the sky, but not so well for the buildings.</td>', 'I like the colors here, but the image has a ''watery'' impressionistic feel, which works well for the sky, but not so well for the buildings.', '2005-11-30 13:47:21.000000', NULL, 1),
(1907741, 263471, 44172, '<td valign="top">great perspective, like the fence post as leading line to the smoke stack, good use of B&amp;W and certainly meets the challenge - nice work :)</td>', 'great perspective, like the fence post as leading line to the smoke stack, good use of B&W and certainly meets the challenge - nice work :)', '2005-11-30 13:47:47.000000', NULL, 1),
(1907744, 262785, 24454, '<td valign="top">PERFECT!!!!   This is such an appealing photo!   One of my most favorites in this challenge!!  10</td>', 'PERFECT!!!!   This is such an appealing photo!   One of my most favorites in this challenge!!  10', '2005-11-30 13:48:36.000000', NULL, 1),
(1907746, 263555, 44172, '<td valign="top">nice macro, coloring and lighting :)</td>', 'nice macro, coloring and lighting :)', '2005-11-30 13:49:22.000000', NULL, 1),
(1907747, 262795, 24454, '<td valign="top">WOW!  Whata can you say, but 10!!!   Oh yeah,  I know something else:  BLUE!<br/> <br/></td>', 'WOW!  Whata can you say, but 10!!!   Oh yeah,  I know something else:  BLUE! ', '2005-11-30 13:49:45.000000', NULL, 1),
(1907748, 263603, 24454, '<td valign="top">Great job!  This is definitely one of the best here!</td>', 'Great job!  This is definitely one of the best here!', '2005-11-30 13:50:19.000000', NULL, 1),
(1907750, 262063, 45857, '<td valign="top">I think you tried to put to much in this picture, it might have been more interesting if you had focused more on the wooden building</td>', 'I think you tried to put to much in this picture, it might have been more interesting if you had focused more on the wooden building', '2005-11-30 13:50:36.000000', NULL, 1),
(1907751, 263244, 24454, '<td valign="top">aMAZING!!!!    Industry at its most beautiful!!!   One of my two favorites in this challenge!   Surely a ribbon winner!!!   10</td>', 'aMAZING!!!!    Industry at its most beautiful!!!   One of my two favorites in this challenge!   Surely a ribbon winner!!!   10', '2005-11-30 13:51:26.000000', NULL, 1),
(1907753, 261571, 24454, '<td valign="top">I love this!   I have to take a photo like this soon for my work!  I hope I can pull it off as good as you have!  Good luck.</td>', 'I love this!   I have to take a photo like this soon for my work!  I hope I can pull it off as good as you have!  Good luck.', '2005-11-30 13:52:30.000000', NULL, 1),
