(1907756, 262067, 45790, '<td valign="top">Most obvious "failed industry" shot I''ve reviewed so far. Nicely done.</td>', 'Most obvious "failed industry" shot I''ve reviewed so far. Nicely done.', '2005-11-30 13:53:40.000000', NULL, 1),
(1907758, 263466, 45790, '<td valign="top">Not that interesting and not particularly industrial.</td>', 'Not that interesting and not particularly industrial.', '2005-11-30 13:54:19.000000', NULL, 1),
