(1907772, 261445, 45790, '<td valign="top">Needs more light on the front. If this is a sunset shot, would be better as a sunrise, for instance.</td>', 'Needs more light on the front. If this is a sunset shot, would be better as a sunrise, for instance.', '2005-11-30 14:03:38.000000', NULL, 1),
(1907779, 262122, 43774, '<td valign="top">This is nice, the lines on the left make a good composition.</td>', 'This is nice, the lines on the left make a good composition.', '2005-11-30 14:07:47.000000', NULL, 1),
(1907780, 262931, 43774, '<td valign="top">Nice composition, looks a little dark to me.</td>', 'Nice composition, looks a little dark to me.', '2005-11-30 14:08:02.000000', NULL, 1),
