(1909082, 261958, 41450, '<td valign="top">I like the ghostly quality of this picture</td>', 'I like the ghostly quality of this picture', '2005-11-30 20:41:31.000000', NULL, 1),
(1909089, 263596, 41450, '<td valign="top">good location,  good color, might be better in black and white.</td>', 'good location,  good color, might be better in black and white.', '2005-11-30 20:42:37.000000', NULL, 1),
(1909090, 263642, 40819, '<td valign="top">Setting but that was expected.</td>', 'Setting but that was expected.', '2005-11-30 20:42:37.000000', NULL, 1),
(1909091, 262394, 43463, '<td valign="top">I love the B&amp;W of this shot for it calls attention to the subjects in this composition. The sky is simple and flat which is very good because it does not add any texture that would distract from the main focus. Love how you have captured the men working on this crane. The B&amp;W gives the photo a feeling of nostaliga - like of days gone by. Surprised that you did not have a title for this one. I have looked at this twice and it really captures the spirit of early industry. BTW, the second time I gazed upon this image I got a flash of imagery of this image being akin to that famous photo of the Flag Raising At Iwo Jima....only this men are raising the crane.</td>', 'I love the B&W of this shot for it calls attention to the subjects in this composition. The sky is simple and flat which is very good because it does not add any texture that would distract from the main focus. Love how you have captured the men working on this crane. The B&W gives the photo a feeling of nostaliga - like of days gone by. Surprised that you did not have a title for this one. I have looked at this twice and it really captures the spirit of early industry. BTW, the second time I gazed upon this image I got a flash of imagery of this image being akin to that famous photo of the Flag Raising At Iwo Jima....only this men are raising the crane.', '2005-11-30 20:43:12.000000', NULL, 1),
(1909095, 263129, 41450, '<td valign="top">nice lighting and color</td>', 'nice lighting and color', '2005-11-30 20:44:00.000000', NULL, 1),
(1909098, 261959, 40819, '<td valign="top">Too much done on this one. Just too much.</td>', 'Too much done on this one. Just too much.', '2005-11-30 20:44:22.000000', NULL, 1),
(1909105, 262795, 41450, '<td valign="top">I like the way the steam is moving - it could have been croped tighter I think.  I think there is too much sides and water.  Th e water takes away from the steam which is more unusual.</td>', 'I like the way the steam is moving - it could have been croped tighter I think.  I think there is too much sides and water.  Th e water takes away from the steam which is more unusual.', '2005-11-30 20:45:17.000000', NULL, 1),
(1909108, 263362, 41450, '<td valign="top">I say tobacco.  Nice contrast. Great day for clouds.</td>', 'I say tobacco.  Nice contrast. Great day for clouds.', '2005-11-30 20:45:58.000000', NULL, 1),
(1909111, 262320, 41450, '<td valign="top">cool subject but I think you could get closer to that mirror and use more of the machine.  the sky isn''t adding to the compoositon or the feel of the photos.</td>', 'cool subject but I think you could get closer to that mirror and use more of the machine.  the sky isn''t adding to the compoositon or the feel of the photos.', '2005-11-30 20:47:26.000000', NULL, 1),
(1909113, 263361, 40430, '<td valign="top">Excellent image, like the abstract quality and color. -8-</td>', 'Excellent image, like the abstract quality and color. -8-', '2005-11-30 20:48:23.000000', NULL, 1),
(1909116, 263628, 43463, '<td valign="top">Oh I love this image!!! Love how the main pipe draws the eye up like a path to follow up to the hopper and then to the full moon (please tell me that that is the moon and not a filter used to dim the sun). Upon gazing upon this photo I instantly thought of the phrase "shoot me to the moon!" And indeed this pipe shoots/leads the eye straight up to the moon rising over the hoppers. Great shot. Great compositon. And the hues are fabulous too!</td>', 'Oh I love this image!!! Love how the main pipe draws the eye up like a path to follow up to the hopper and then to the full moon (please tell me that that is the moon and not a filter used to dim the sun). Upon gazing upon this photo I instantly thought of the phrase "shoot me to the moon!" And indeed this pipe shoots/leads the eye straight up to the moon rising over the hoppers. Great shot. Great compositon. And the hues are fabulous too!', '2005-11-30 20:49:02.000000', NULL, 1),
(1909117, 263244, 41450, '<td valign="top">good feel of power and scope.  Nice exposure and I like the milky water or is that snow?</td>', 'good feel of power and scope.  Nice exposure and I like the milky water or is that snow?', '2005-11-30 20:49:10.000000', NULL, 1),
