INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1909491, 263715, 10263, '<td valign="top">The colors are great here. Looks like a Christmas tree :) The trees on each side are a nice touch but the bright color on the bush on the right seems a bit much.</td>', 'The colors are great here. Looks like a Christmas tree :) The trees on each side are a nice touch but the bright color on the bush on the right seems a bit much.', '2005-11-30 22:32:27.000000', NULL, 1),
(1909493, 262516, 10263, '<td valign="top">The lines are great and the grain works well here.</td>', 'The lines are great and the grain works well here.', '2005-11-30 22:33:51.000000', NULL, 1),
(1909505, 262511, 10263, '<td valign="top">The sky is a definate wow. Great capture on the sun rays.</td>', 'The sky is a definate wow. Great capture on the sun rays.', '2005-11-30 22:36:33.000000', NULL, 1),
(1909508, 262788, 45524, '<td valign="top">This is an incredible pic. Super sharp focus and great effect with longer shutter speed. This is one of my Ribbon choices. 10</td>', 'This is an incredible pic. Super sharp focus and great effect with longer shutter speed. This is one of my Ribbon choices. 10', '2005-11-30 22:37:19.000000', NULL, 1),
(1909523, 262795, 45524, '<td valign="top">Great photo, nice choice with shutter speed. Well done. Top 10 photo here in my book.</td>', 'Great photo, nice choice with shutter speed. Well done. Top 10 photo here in my book.', '2005-11-30 22:39:39.000000', NULL, 1),
(1909548, 261959, 45524, '<td valign="top">This is a really neat photo, but looks really overprocessed.</td>', 'This is a really neat photo, but looks really overprocessed.', '2005-11-30 22:45:47.000000', NULL, 1),
(1909555, 263548, 10263, '<td valign="top">I  like this. Simple lines, great composition.</td>', 'I  like this. Simple lines, great composition.', '2005-11-30 22:47:02.000000', NULL, 1),
(1909557, 263047, 48487, '<td valign="top">Fantastic shot.  So little communicates so much.  Great depth of field.  The increased focus going up the stanchion seems to imply getting more and more serious about the message.</td>', 'Fantastic shot.  So little communicates so much.  Great depth of field.  The increased focus going up the stanchion seems to imply getting more and more serious about the message.', '2005-11-30 22:47:29.000000', NULL, 1),
(1909561, 263171, 26313, '<td valign="top">I like the composition of this a lot, though if it were possible to back out a little and get the bucket in the shot that might have added something. I''d imagine that would have introduced a bunch of clutter from the background though, so cropping it like this was probably a good choice. Frankly, I think the lighting is terrible in terms of the reflections on the bottom of the arm, and the evidence of the light that has been cropped out in the lower left. The direction of the lighting is pretty good though. The colouring seems a little off, and I''m not sure if that''s just because of the nature of the lighting and the fact that it is a night shot, or if has to do with the post processing. I would try it in black and white, as that is an easy way to take care of the strange colour casts you sometimes get in night shots (from sodium vapour lamps or whatever the hell they are).</td>', 'I like the composition of this a lot, though if it were possible to back out a little and get the bucket in the shot that might have added something. I''d imagine that would have introduced a bunch of clutter from the background though, so cropping it like this was probably a good choice. Frankly, I think the lighting is terrible in terms of the reflections on the bottom of the arm, and the evidence of the light that has been cropped out in the lower left. The direction of the lighting is pretty good though. The colouring seems a little off, and I''m not sure if that''s just because of the nature of the lighting and the fact that it is a night shot, or if has to do with the post processing. I would try it in black and white, as that is an easy way to take care of the strange colour casts you sometimes get in night shots (from sodium vapour lamps or whatever the hell they are).', '2005-11-30 22:47:58.000000', NULL, 1),
(1909568, 261827, 45524, '<td valign="top">I gave this photo a 9, I think with a B&amp;W theme its a 10. Nice symetry and good timing on the shot. Well done.</td>', 'I gave this photo a 9, I think with a B&W theme its a 10. Nice symetry and good timing on the shot. Well done.', '2005-11-30 22:48:52.000000', NULL, 1),
(1909583, 263726, 48487, '<td valign="top">Very dramatic lighting.</td>', 'Very dramatic lighting.', '2005-11-30 22:51:39.000000', NULL, 1),
(1909598, 263468, 45524, '<td valign="top">Wonderful perspective on this. Definatley should be a top 20 photo. Well done. 8</td>', 'Wonderful perspective on this. Definatley should be a top 20 photo. Well done. 8', '2005-11-30 22:53:22.000000', NULL, 1),
(1909609, 263501, 48487, '<td valign="top">Branches agains the light add real depth and a very dramatic effect.  Great lighting.</td>', 'Branches agains the light add real depth and a very dramatic effect.  Great lighting.', '2005-11-30 22:54:48.000000', NULL, 1),
(1909614, 263362, 45524, '<td valign="top">Very dramatic lighting, nice timing as well. 8</td>', 'Very dramatic lighting, nice timing as well. 8', '2005-11-30 22:55:16.000000', NULL, 1),
(1909656, 262983, 48487, '<td valign="top">Love the perspective.  Very strong and dramatic.</td>', 'Love the perspective.  Very strong and dramatic.', '2005-11-30 23:02:08.000000', NULL, 1),
(1909761, 263715, 48487, '<td valign="top">I''m afraid the bright foreground is not, in my opinion, consistent with the rest of the photograph.  Seems distracting to me.</td>', 'I''m afraid the bright foreground is not, in my opinion, consistent with the rest of the photograph.  Seems distracting to me.', '2005-11-30 23:20:35.000000', NULL, 1),
(1909797, 262558, 42100, '<td valign="top">Very out of this world feel to this photo.  The lighting and contrast in this photo are amazing.  Excellent!</td>', 'Very out of this world feel to this photo.  The lighting and contrast in this photo are amazing.  Excellent!', '2005-11-30 23:27:53.000000', NULL, 1),
(1909798, 262320, 33145, '<td valign="top">This is soooooo MAAATTTT DAAAAMMMONNNNNNN</td>', 'This is soooooo MAAATTTT DAAAAMMMONNNNNNN', '2005-11-30 23:28:11.000000', NULL, 1),
(1909800, 262795, 43463, '<td valign="top">Love how the reflections in the water mimic that of multiple towers when there exists one  that main stackin the center of the shot  that is blowing great plumes of smoke. Visually appealing to look upon. Night always turns what is by day a dirty dingy looking factory into something quite magical by night. Colors are wonderful too.</td>', 'Love how the reflections in the water mimic that of multiple towers when there exists one  that main stackin the center of the shot  that is blowing great plumes of smoke. Visually appealing to look upon. Night always turns what is by day a dirty dingy looking factory into something quite magical by night. Colors are wonderful too.', '2005-11-30 23:28:37.000000', NULL, 1),
(1909801, 262835, 42256, '<td valign="top">I like the use of the negative space and the star burst.</td>', 'I like the use of the negative space and the star burst.', '2005-11-30 23:28:47.000000', NULL, 1),
(1909802, 263491, 42100, '<td valign="top">Unique angle and compostion. Great photo and very creative!</td>', 'Unique angle and compostion. Great photo and very creative!', '2005-11-30 23:29:04.000000', NULL, 1),
(1909812, 262251, 42100, '<td valign="top">Very creative take on the challenge.  Excellent compostion and lighting.  I hope you reward your model well for posing like that with those sparks.</td>', 'Very creative take on the challenge.  Excellent compostion and lighting.  I hope you reward your model well for posing like that with those sparks.', '2005-11-30 23:31:48.000000', NULL, 1),
(1909818, 263135, 42100, '<td valign="top">Very well composed.  The B&amp;W works perfectly with this photo.  Nicely done!</td>', 'Very well composed.  The B&W works perfectly with this photo.  Nicely done!', '2005-11-30 23:33:04.000000', NULL, 1),
(1909819, 262785, 42256, '<td valign="top">Finally someone with the people involved in the industries rather than just the industry.  Like the look captured!</td>', 'Finally someone with the people involved in the industries rather than just the industry.  Like the look captured!', '2005-11-30 23:33:27.000000', NULL, 1),
(1909822, 263732, 42100, '<td valign="top">Good eye for this photo.  This is definately not the obvious shot and you executed it very well.</td>', 'Good eye for this photo.  This is definately not the obvious shot and you executed it very well.', '2005-11-30 23:34:23.000000', NULL, 1),
(1909831, 263484, 42100, '<td valign="top">Original angle on this photo.  I like this one alot, the tones are perfect and the composition is excellent as well.</td>', 'Original angle on this photo.  I like this one alot, the tones are perfect and the composition is excellent as well.', '2005-11-30 23:35:56.000000', NULL, 1),
(1909833, 263462, 42256, '<td valign="top">Nice composition !! I like the way the industry is framed with the pipeline !</td>', 'Nice composition !! I like the way the industry is framed with the pipeline !', '2005-11-30 23:36:02.000000', NULL, 1),
(1909836, 263532, 43463, '<td valign="top">Very effective presentation and composition. I like how the composition is closely cropped to show the viewer a vertical presentation of the scene. In this way the shape mimics the tall column and the plume of "smoke" that is rising in the air. Also, I don''t know if this was planned for the shot or a lucky stroke, but those copper hued plants in the forground also have a vertical presentation in there natural shape. The colors of those plants adds a burst of bright and vibrant color to a scene that otherwise would make us think "cold". We see the image and with the whiteness of the snow and sky we are instantly made to feel the cold but that burst of color from the plants adds a bit of unexpected warmth to the scene. Nicely captured.</td>', 'Very effective presentation and composition. I like how the composition is closely cropped to show the viewer a vertical presentation of the scene. In this way the shape mimics the tall column and the plume of "smoke" that is rising in the air. Also, I don''t know if this was planned for the shot or a lucky stroke, but those copper hued plants in the forground also have a vertical presentation in there natural shape. The colors of those plants adds a burst of bright and vibrant color to a scene that otherwise would make us think "cold". We see the image and with the whiteness of the snow and sky we are instantly made to feel the cold but that burst of color from the plants adds a bit of unexpected warmth to the scene. Nicely captured.', '2005-11-30 23:36:26.000000', NULL, 1),
(1909842, 262122, 42100, '<td valign="top">Excellent compostion and great leading lines.  Great photo!</td>', 'Excellent compostion and great leading lines.  Great photo!', '2005-11-30 23:37:02.000000', NULL, 1),
(1909843, 263367, 42256, '<td valign="top">Nice colors !</td>', 'Nice colors !', '2005-11-30 23:37:03.000000', NULL, 1),
(1909847, 261679, 45857, '<td valign="top">Love the patterns here, of course, but spotting the cleaners was a gem.</td>', 'Love the patterns here, of course, but spotting the cleaners was a gem.', '2005-11-30 23:37:31.000000', NULL, 1),
(1909857, 263766, 42256, '<td valign="top">Finally one industry I can relate too !</td>', 'Finally one industry I can relate too !', '2005-11-30 23:38:20.000000', NULL, 1),
(1909862, 263469, 45857, '<td valign="top">Strak industrious image, the B&amp;W works well</td>', 'Strak industrious image, the B&W works well', '2005-11-30 23:38:55.000000', NULL, 1),
(1909871, 263188, 42100, '<td valign="top">Very nicely composed photograph.   There is nice detail in this photo and I think a shrper image would really bring it out.</td>', 'Very nicely composed photograph.   There is nice detail in this photo and I think a shrper image would really bring it out.', '2005-11-30 23:40:39.000000', NULL, 1),
(1909883, 262978, 42100, '<td valign="top">The detail and contrast is great in the smoke coming off the stacks.  I know its tough to get close to these places, but I think a much tighter shot would be nicer.</td>', 'The detail and contrast is great in the smoke coming off the stacks.  I know its tough to get close to these places, but I think a much tighter shot would be nicer.', '2005-11-30 23:43:35.000000', NULL, 1),
(1909897, 263619, 42100, '<td valign="top">The power lines flowing through the photo make for an interesting composition.  But this photo just seems to dark and oversaturated.</td>', 'The power lines flowing through the photo make for an interesting composition.  But this photo just seems to dark and oversaturated.', '2005-11-30 23:46:05.000000', NULL, 1),
(1909901, 262071, 43463, '<td valign="top">Visually captivating because your eye is immediately attracted to the vibrant hues of oranges seen illuminating this "tunnel". As your eye follows the path and journeys forward into this light tunnel we see a plume of flame like an upside down funnel cloud. There are people gathered around either working and/or observing the plume of light and heat. Interesting - I won''t know what exactly I am looking at until after the results are in and I can read the description. Nonetheless it is visually captivating  as I said earlier. Nicely done.</td>', 'Visually captivating because your eye is immediately attracted to the vibrant hues of oranges seen illuminating this "tunnel". As your eye follows the path and journeys forward into this light tunnel we see a plume of flame like an upside down funnel cloud. There are people gathered around either working and/or observing the plume of light and heat. Interesting - I won''t know what exactly I am looking at until after the results are in and I can read the description. Nonetheless it is visually captivating  as I said earlier. Nicely done.', '2005-11-30 23:46:26.000000', NULL, 1),
(1909922, 261490, 42100, '<td valign="top">The lighting and composition in this photo are excellent.  But the overlapping of the chainlink and the powerstation structure is too busy and confusing.</td>', 'The lighting and composition in this photo are excellent.  But the overlapping of the chainlink and the powerstation structure is too busy and confusing.', '2005-11-30 23:49:30.000000', NULL, 1),
(1909946, 263500, 42100, '<td valign="top">You colors are good and it has lots of great subject matter.  But there seems to be far too much going on in this photo.  Don''t be afraid to move in on your subject and simplify.</td>', 'You colors are good and it has lots of great subject matter.  But there seems to be far too much going on in this photo.  Don''t be afraid to move in on your subject and simplify.', '2005-11-30 23:52:34.000000', NULL, 1),
(1909966, 263655, 42100, '<td valign="top">Great exposure on the sky, but the shoreline is too dark and some great detail is lost.</td>', 'Great exposure on the sky, but the shoreline is too dark and some great detail is lost.', '2005-11-30 23:54:55.000000', NULL, 1),
(1909987, 263188, 45857, '<td valign="top">Dramatic close up look at industrial crud, but not sure the tremble of energy works here.</td>', 'Dramatic close up look at industrial crud, but not sure the tremble of energy works here.', '2005-11-30 23:57:18.000000', NULL, 1),
(1909990, 262023, 35491, '<td valign="top">The statue needs more light</td>', 'The statue needs more light', '2005-11-30 23:57:41.000000', NULL, 1),
(1910039, 261958, 45857, '<td valign="top">Love the busy feel here and your color choice enhances the blah packaging.</td>', 'Love the busy feel here and your color choice enhances the blah packaging.', '2005-12-01 00:03:20.000000', NULL, 1),
(1910306, 261361, 45857, '<td valign="top">Good dirty grainy feel.</td>', 'Good dirty grainy feel.', '2005-12-01 00:40:31.000000', NULL, 1),
(1910321, 263216, 45928, '<td valign="top">I love this picture, I just wish it were a bit sharper around the rocks, but I still give it a ten.</td>', 'I love this picture, I just wish it were a bit sharper around the rocks, but I still give it a ten.', '2005-12-01 00:44:49.000000', NULL, 1),
