(1910842, 263128, 47508, '<td valign="top">very nice.</td>', 'very nice.', '2005-12-01 02:36:15.000000', NULL, 1),
(1910845, 261413, 38666, '<td valign="top">I think your title, recapitulation, is in reference to the smaller plane, as an echo to the larger one? I''m not sure I get it, or that it makes sence or has anything to do with this challenge. That said, it is an otherwise very intelligent comment on urban sprawl and development and would fit well in a newspaper story with a similar interest. That was supposed to be a compliment. Also, I''d rather see this cropped, or showing more of that thing on the bottom. As it is, it''s a bad distraction. 6/10</td>', 'I think your title, recapitulation, is in reference to the smaller plane, as an echo to the larger one? I''m not sure I get it, or that it makes sence or has anything to do with this challenge. That said, it is an otherwise very intelligent comment on urban sprawl and development and would fit well in a newspaper story with a similar interest. That was supposed to be a compliment. Also, I''d rather see this cropped, or showing more of that thing on the bottom. As it is, it''s a bad distraction. 6/10', '2005-12-01 02:37:49.000000', NULL, 1),
