(1912755, 263129, 45857, '<td valign="top">Really good image, interesting poetic title, certainly not the first thing to come to mind.</td>', 'Really good image, interesting poetic title, certainly not the first thing to come to mind.', '2005-12-01 13:34:07.000000', NULL, 1),
(1912764, 262836, 45857, '<td valign="top">Nice dark industrial feel. Thought provoking title, at first innocent, but actually shows a profound understanding of nature.</td>', 'Nice dark industrial feel. Thought provoking title, at first innocent, but actually shows a profound understanding of nature.', '2005-12-01 13:36:46.000000', NULL, 1),
(1912766, 262861, 16950, '<td valign="top">Finally something different!</td>', 'Finally something different!', '2005-12-01 13:37:06.000000', NULL, 1),
(1912789, 262220, 16950, '<td valign="top">I like this idea, but personally I would have liked to have seen the "end" in focus rather than the beginning.</td>', 'I like this idea, but personally I would have liked to have seen the "end" in focus rather than the beginning.', '2005-12-01 13:43:27.000000', NULL, 1),
(1912805, 263216, 16950, '<td valign="top">I love the starkness of this shot!</td>', 'I love the starkness of this shot!', '2005-12-01 13:47:16.000000', NULL, 1),
(1912806, 261519, 45857, '<td valign="top">Good landscape, maybe a degree or two to the right. Like the grass in the foreground, warms it up.</td>', 'Good landscape, maybe a degree or two to the right. Like the grass in the foreground, warms it up.', '2005-12-01 13:47:26.000000', NULL, 1),
(1912814, 262841, 45857, '<td valign="top">Bold abstraction</td>', 'Bold abstraction', '2005-12-01 13:49:03.000000', NULL, 1),
(1912822, 263616, 45857, '<td valign="top">A little tilted but good perspective</td>', 'A little tilted but good perspective', '2005-12-01 13:50:54.000000', NULL, 1),
(1912842, 263538, 45857, '<td valign="top">(_____) Good!  Fill in the blank, ran out of superlatives. Everything works.</td>', '(_____) Good!  Fill in the blank, ran out of superlatives. Everything works.', '2005-12-01 13:55:36.000000', NULL, 1),
(1912853, 261417, 45857, '<td valign="top">Obviously not something you carry for camera repairs.<br/>You certainly captured the essence of industrial strength.</td>', 'Obviously not something you carry for camera repairs.You certainly captured the essence of industrial strength.', '2005-12-01 13:59:15.000000', NULL, 1),
(1912860, 263122, 45857, '<td valign="top">Love it...chuckle, chuckle.</td>', 'Love it...chuckle, chuckle.', '2005-12-01 14:01:20.000000', NULL, 1),
(1912891, 263446, 45857, '<td valign="top">Dark mysterious world of petrochemistry. Serving your energy needs for the next 20 years or so. Ok, like your shot, the tanker is a great touch, I wonder if a bit more exposure time would have made a difference</td>', 'Dark mysterious world of petrochemistry. Serving your energy needs for the next 20 years or so. Ok, like your shot, the tanker is a great touch, I wonder if a bit more exposure time would have made a difference', '2005-12-01 14:07:08.000000', NULL, 1),
(1912898, 262521, 45857, '<td valign="top">Clean, simple, elegant</td>', 'Clean, simple, elegant', '2005-12-01 14:08:42.000000', NULL, 1),
(1912903, 263712, 45857, '<td valign="top">Nice use of contradiction.</td>', 'Nice use of contradiction.', '2005-12-01 14:09:54.000000', NULL, 1),
(1912927, 263171, 45857, '<td valign="top">Good study of angles and spaces. You do seem to have a few hot pixels, oops, they''re stars  :)</td>', 'Good study of angles and spaces. You do seem to have a few hot pixels, oops, they''re stars  :)', '2005-12-01 14:14:08.000000', NULL, 1),
(1912936, 263256, 45857, '<td valign="top">Good landscape, I think the silhouette works well here.</td>', 'Good landscape, I think the silhouette works well here.', '2005-12-01 14:17:19.000000', NULL, 1),
(1912949, 262931, 45857, '<td valign="top">Yeppers, industrial grade garden tools.<br/>Good image, like the lighting and dark sky background. Really good place to stand, perhaps a neglected aspect of photography.</td>', 'Yeppers, industrial grade garden tools.Good image, like the lighting and dark sky background. Really good place to stand, perhaps a neglected aspect of photography.', '2005-12-01 14:20:35.000000', NULL, 1),
(1912963, 262976, 45857, '<td valign="top">Great effect, talk about hyperfocus. This has all the right things for me.</td>', 'Great effect, talk about hyperfocus. This has all the right things for me.', '2005-12-01 14:22:46.000000', NULL, 1),
(1912967, 263548, 45925, '<td valign="top">nice shot.  i love the blue sky backround.</td>', 'nice shot.  i love the blue sky backround.', '2005-12-01 14:24:41.000000', NULL, 1),
(1912969, 263231, 45925, '<td valign="top">nice shot the sky is just beautiful.</td>', 'nice shot the sky is just beautiful.', '2005-12-01 14:24:57.000000', NULL, 1),
