INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1913127, 263088, 45857, '<td valign="top">Now this is art!</td>', 'Now this is art!', '2005-12-01 14:57:01.000000', NULL, 1),
(1913132, 262991, 16950, '<td valign="top">I think this would have made a better shot if it wasn''t so over exposed.  It''s hard to see any detail with the brightness of the lights.</td>', 'I think this would have made a better shot if it wasn''t so over exposed.  It''s hard to see any detail with the brightness of the lights.', '2005-12-01 14:57:54.000000', NULL, 1),
(1913133, 261417, 739, '<td valign="top">I think you could have used an extra light source to give this more even lighting.  I think that will give this tool more prominence.  With one half of it in the shadows, it''s more of an art piece than a tool.</td>', 'I think you could have used an extra light source to give this more even lighting.  I think that will give this tool more prominence.  With one half of it in the shadows, it''s more of an art piece than a tool.', '2005-12-01 14:58:03.000000', NULL, 1),
(1913135, 263128, 16950, '<td valign="top">Not sure this says ''Industrial'' to me.</td>', 'Not sure this says ''Industrial'' to me.', '2005-12-01 14:58:28.000000', NULL, 1),
(1913157, 262795, 16950, '<td valign="top">This was my favorite of the challenge.  Love the reflections.</td>', 'This was my favorite of the challenge.  Love the reflections.', '2005-12-01 15:01:53.000000', NULL, 1),
(1913161, 262788, 16950, '<td valign="top">Great shot.  One of my favorites.</td>', 'Great shot.  One of my favorites.', '2005-12-01 15:02:21.000000', NULL, 1),
(1913162, 263361, 739, '<td valign="top">Interesting object.  I was looking at this and couldn''t figure out what was bothering me.  After a long while, I used a piece of paper to re-crop this so that the reflection surface is not exactly centered on the picture.  I liked that better.</td>', 'Interesting object.  I was looking at this and couldn''t figure out what was bothering me.  After a long while, I used a piece of paper to re-crop this so that the reflection surface is not exactly centered on the picture.  I liked that better.', '2005-12-01 15:02:34.000000', NULL, 1),
(1913167, 262988, 16950, '<td valign="top">Love the colors and reflections.  Nice shot.</td>', 'Love the colors and reflections.  Nice shot.', '2005-12-01 15:02:58.000000', NULL, 1),
(1913174, 263766, 24013, '<td valign="top">cool.  wouldn''t work nearly as well without the golden "ocean" in the background.</td>', 'cool.  wouldn''t work nearly as well without the golden "ocean" in the background.', '2005-12-01 15:03:44.000000', NULL, 1),
(1913181, 263122, 24013, '<td valign="top">wow.  just a tiny bit more contrast maybe.  i love the great patterns and shapes.  gorgeous!</td>', 'wow.  just a tiny bit more contrast maybe.  i love the great patterns and shapes.  gorgeous!', '2005-12-01 15:05:23.000000', NULL, 1),
(1913182, 263478, 739, '<td valign="top">You did a great job capturing this.  Love the effect.</td>', 'You did a great job capturing this.  Love the effect.', '2005-12-01 15:05:37.000000', NULL, 1),
(1913194, 263628, 16950, '<td valign="top">I love this.  One of my top five.</td>', 'I love this.  One of my top five.', '2005-12-01 15:08:04.000000', NULL, 1),
(1913198, 263287, 44980, '<td valign="top">Suit the challenge well. I find this a bit grainy and soft though.</td>', 'Suit the challenge well. I find this a bit grainy and soft though.', '2005-12-01 15:09:24.000000', NULL, 1),
(1913203, 261763, 739, '<td valign="top">Are you filming the anchor or the ship? Difficult to tell..</td>', 'Are you filming the anchor or the ship? Difficult to tell..', '2005-12-01 15:10:19.000000', NULL, 1),
(1913208, 262951, 739, '<td valign="top">You should have cropped out the cars; they are a distraction to you picture.</td>', 'You should have cropped out the cars; they are a distraction to you picture.', '2005-12-01 15:12:07.000000', NULL, 1),
(1913212, 261959, 44980, '<td valign="top">Good composition. Too much alteration for my liking though.</td>', 'Good composition. Too much alteration for my liking though.', '2005-12-01 15:12:57.000000', NULL, 1),
(1913218, 263565, 739, '<td valign="top">Would have preferred the bolt to be also in focus.</td>', 'Would have preferred the bolt to be also in focus.', '2005-12-01 15:14:30.000000', NULL, 1),
(1913221, 262984, 739, '<td valign="top">Awesome view, but don''t see any industry here.</td>', 'Awesome view, but don''t see any industry here.', '2005-12-01 15:15:22.000000', NULL, 1),
(1913261, 262432, 44980, '<td valign="top">Nice idea and angle. A bit soft though. Is it out of focus?</td>', 'Nice idea and angle. A bit soft though. Is it out of focus?', '2005-12-01 15:30:57.000000', NULL, 1),
(1913269, 263619, 44980, '<td valign="top">Those colours appear unnatural to me. I think your picture needs a bit of a levels boost. Nice pic though.</td>', 'Those colours appear unnatural to me. I think your picture needs a bit of a levels boost. Nice pic though.', '2005-12-01 15:32:06.000000', NULL, 1),
(1913279, 263500, 44980, '<td valign="top">Too much sharpening has given those edges an unnatural glow.</td>', 'Too much sharpening has given those edges an unnatural glow.', '2005-12-01 15:35:21.000000', NULL, 1),
(1913296, 262984, 44980, '<td valign="top">Unbelievable picture. Love your colours, the size, everything. If this doesn''t win, I''d be really surprised.</td>', 'Unbelievable picture. Love your colours, the size, everything. If this doesn''t win, I''d be really surprised.', '2005-12-01 15:40:33.000000', NULL, 1),
(1913302, 263257, 24642, '<td valign="top">I really like the subject matter, It''s close to my interest.  The cropping works well for the composition.  The light from the welding gear is powerful.  A viewpoint slightly to the left would give the numbers some more space but I guess that would move the welder too near the center.  Thumbs up for a clean geometric composition with the interest of a working man.  -8</td>', 'I really like the subject matter, It''s close to my interest.  The cropping works well for the composition.  The light from the welding gear is powerful.  A viewpoint slightly to the left would give the numbers some more space but I guess that would move the welder too near the center.  Thumbs up for a clean geometric composition with the interest of a working man.  -8', '2005-12-01 15:43:09.000000', NULL, 1),
(1913308, 263128, 45857, '<td valign="top">I can almost read the lable on the bottle .... Caution: Consumption during photograpy may result in low scores.<br/>I''m afraid I don''t see how this demonstrates industrial, even considering the entertainment industry.</td>', 'I can almost read the lable on the bottle .... Caution: Consumption during photograpy may result in low scores.I''m afraid I don''t see how this demonstrates industrial, even considering the entertainment industry.', '2005-12-01 15:45:49.000000', NULL, 1),
(1913321, 262795, 24642, '<td valign="top">Good composition.  The blend of natural and artificial light works very well.  The interplay between the smoke and the sky is brilliant so are the reflections.</td>', 'Good composition.  The blend of natural and artificial light works very well.  The interplay between the smoke and the sky is brilliant so are the reflections.', '2005-12-01 15:48:34.000000', NULL, 1),
(1913323, 261958, 44980, '<td valign="top">I love the colours. It''s so "City of Lost Children"</td>', 'I love the colours. It''s so "City of Lost Children"', '2005-12-01 15:49:37.000000', NULL, 1),
(1913331, 262929, 45857, '<td valign="top">Unearthly feel, almost sci-fi.</td>', 'Unearthly feel, almost sci-fi.', '2005-12-01 15:53:45.000000', NULL, 1),
(1913337, 263565, 24642, '<td valign="top">Good title.  The lighting and reflections work well.</td>', 'Good title.  The lighting and reflections work well.', '2005-12-01 15:55:02.000000', NULL, 1),
(1913342, 263250, 45857, '<td valign="top">Sorry, too clean for a railway station   :)<br/>Very good, I like the lines and patterns.</td>', 'Sorry, too clean for a railway station   :)Very good, I like the lines and patterns.', '2005-12-01 15:55:54.000000', NULL, 1),
(1913351, 263041, 9671, '<td valign="top">I hope you have a high resolution file of this thats sharper than this jpeg--definitly a framable capture!</td>', 'I hope you have a high resolution file of this thats sharper than this jpeg--definitly a framable capture!', '2005-12-01 15:58:06.000000', NULL, 1),
(1913354, 261627, 24642, '<td valign="top">I really like the subject and the viewpoint.   These silos look very sci-fi and dramatic, they sure look like aliens.</td>', 'I really like the subject and the viewpoint.   These silos look very sci-fi and dramatic, they sure look like aliens.', '2005-12-01 15:58:54.000000', NULL, 1),
(1913362, 263330, 24642, '<td valign="top">I like the subject and it''s abstract/geometric qualities.  Perhaps a closer viewpoint or a tighter crop would make this photo stronger.</td>', 'I like the subject and it''s abstract/geometric qualities.  Perhaps a closer viewpoint or a tighter crop would make this photo stronger.', '2005-12-01 16:02:09.000000', NULL, 1),
(1913371, 263759, 41999, '<td valign="top">I like this. Image could be improved by using the transform tool to make all the verticals vertical.</td>', 'I like this. Image could be improved by using the transform tool to make all the verticals vertical.', '2005-12-01 16:05:41.000000', NULL, 1),
(1913466, 262067, 48750, '<td valign="top">theres too much going on...i dont know where to look....</td>', 'theres too much going on...i dont know where to look....', '2005-12-01 16:34:40.000000', NULL, 1),
(1913471, 263243, 41999, '<td valign="top">Good composition. Nevertheless, the picture could have been better: were the tool spinning, this would be a dynamic picture; were some chips flying, the focus of attention would be drawn to that lower right rule-of-thirds point.</td>', 'Good composition. Nevertheless, the picture could have been better: were the tool spinning, this would be a dynamic picture; were some chips flying, the focus of attention would be drawn to that lower right rule-of-thirds point.', '2005-12-01 16:35:49.000000', NULL, 1),
(1913472, 262606, 48750, '<td valign="top">sorry....its kinda boring...</td>', 'sorry....its kinda boring...', '2005-12-01 16:35:52.000000', NULL, 1),
(1913481, 263548, 43011, '<td valign="top">weirdly framed: especially the lefthand side</td>', 'weirdly framed: especially the lefthand side', '2005-12-01 16:38:28.000000', NULL, 1),
(1913488, 263031, 43011, '<td valign="top">nice B&amp;W</td>', 'nice B&W', '2005-12-01 16:39:24.000000', NULL, 1),
(1913491, 263258, 45857, '<td valign="top">Sensual tools, oh my!</td>', 'Sensual tools, oh my!', '2005-12-01 16:40:51.000000', NULL, 1),
(1913495, 262071, 45857, '<td valign="top">Fascinating image, certainly an inside look at industry.</td>', 'Fascinating image, certainly an inside look at industry.', '2005-12-01 16:42:18.000000', NULL, 1),
(1913509, 263418, 45857, '<td valign="top">Ice bound fleet, good composition, the ''rust bucket'' certainly conveys the message.</td>', 'Ice bound fleet, good composition, the ''rust bucket'' certainly conveys the message.', '2005-12-01 16:45:44.000000', NULL, 1),
(1913513, 262384, 45857, '<td valign="top">Nice clean industrious look</td>', 'Nice clean industrious look', '2005-12-01 16:47:04.000000', NULL, 1),
(1913527, 262908, 22734, '<td valign="top">What sheer strength in presentation!</td>', 'What sheer strength in presentation!', '2005-12-01 16:53:50.000000', NULL, 1),
(1913539, 262795, 45857, '<td valign="top">Great job, love the updraft.</td>', 'Great job, love the updraft.', '2005-12-01 16:58:13.000000', NULL, 1),
(1913554, 263362, 22734, '<td valign="top">The strong visual here is captivating and very moving. The post processing here has been expertly handled to portray a wonderful feeling. Bumping up.</td>', 'The strong visual here is captivating and very moving. The post processing here has been expertly handled to portray a wonderful feeling. Bumping up.', '2005-12-01 17:01:52.000000', NULL, 1),
(1913562, 262251, 22734, '<td valign="top">One of those images that can adorn a calendar and make it a collector''s item. Nice work.</td>', 'One of those images that can adorn a calendar and make it a collector''s item. Nice work.', '2005-12-01 17:04:25.000000', NULL, 1),
(1913564, 263248, 22734, '<td valign="top">A wonderful visual expanse to toy the senses. Bumping up.</td>', 'A wonderful visual expanse to toy the senses. Bumping up.', '2005-12-01 17:05:25.000000', NULL, 1),
