(1915439, 263362, 31239, '<td valign="top">great colours</td>', 'great colours', '2005-12-02 07:30:00.000000', NULL, 1),
(1915443, 262034, 39349, '<td valign="top">Antique stuff is always good to me. I really like how you''ve setup this shot. The pulley system along with the period style buildings really make this a step back in time. Bravo!</td>', 'Antique stuff is always good to me. I really like how you''ve setup this shot. The pulley system along with the period style buildings really make this a step back in time. Bravo!', '2005-12-02 07:32:31.000000', NULL, 1),
(1915454, 262558, 33732, '<td valign="top">Very well composed.  And the sky color really give a feeling of industrial.</td>', 'Very well composed.  And the sky color really give a feeling of industrial.', '2005-12-02 07:47:19.000000', NULL, 1),
(1915455, 261959, 33732, '<td valign="top">Very catching.  The contrast is great. Blue sky seems unlikely but is great.</td>', 'Very catching.  The contrast is great. Blue sky seems unlikely but is great.', '2005-12-02 07:47:37.000000', NULL, 1),
(1915458, 262788, 33732, '<td valign="top">The power lines are what they are.  The reflections help make the photo.  The long exposure helps create the at work effect.  Good luck.</td>', 'The power lines are what they are.  The reflections help make the photo.  The long exposure helps create the at work effect.  Good luck.', '2005-12-02 07:49:07.000000', NULL, 1),
(1915459, 262118, 33732, '<td valign="top">Nice to see this example. The foreground is interesting.  The 7207 must have limited what you could do on this.</td>', 'Nice to see this example. The foreground is interesting.  The 7207 must have limited what you could do on this.', '2005-12-02 07:50:22.000000', NULL, 1),
