INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1915462, 262785, 33732, '<td valign="top">A second look makes this appealing.  Very good effect.  The lighting looks very close to a single light source.</td>', 'A second look makes this appealing.  Very good effect.  The lighting looks very close to a single light source.', '2005-12-02 07:53:33.000000', NULL, 1),
(1915464, 262984, 33732, '<td valign="top">Very good composure and the lighting is very unususal.</td>', 'Very good composure and the lighting is very unususal.', '2005-12-02 07:54:35.000000', NULL, 1),
(1915465, 263484, 33732, '<td valign="top">Interesting but hard to understand.</td>', 'Interesting but hard to understand.', '2005-12-02 07:55:19.000000', NULL, 1),
(1915466, 262071, 33732, '<td valign="top">Very dramatic.</td>', 'Very dramatic.', '2005-12-02 07:56:10.000000', NULL, 1),
(1915468, 261361, 33732, '<td valign="top">The grain seems to hurt this photo.  Interesting patches of light in the sky.</td>', 'The grain seems to hurt this photo.  Interesting patches of light in the sky.', '2005-12-02 07:57:40.000000', NULL, 1),
(1915470, 262099, 33732, '<td valign="top">I like this.  With the subject the presentation is appropriate.</td>', 'I like this.  With the subject the presentation is appropriate.', '2005-12-02 07:58:40.000000', NULL, 1),
(1915471, 263758, 33732, '<td valign="top">Not sure what we have but the factory feeling is present.</td>', 'Not sure what we have but the factory feeling is present.', '2005-12-02 07:59:20.000000', NULL, 1),
(1915472, 262957, 33732, '<td valign="top">This is industrial and the person adds to the photo.  If the room light was less the background would be lost.</td>', 'This is industrial and the person adds to the photo.  If the room light was less the background would be lost.', '2005-12-02 08:00:29.000000', NULL, 1),
(1915473, 263532, 33732, '<td valign="top">Looks cold. The steam gives the active work feel. If you moved to the right could you eliminate the power poles on the mtn?</td>', 'Looks cold. The steam gives the active work feel. If you moved to the right could you eliminate the power poles on the mtn?', '2005-12-02 08:02:25.000000', NULL, 1),
(1915474, 263236, 33732, '<td valign="top">Power lines are tough.  The truck is nice.</td>', 'Power lines are tough.  The truck is nice.', '2005-12-02 08:03:11.000000', NULL, 1),
(1915479, 263734, 39349, '<td valign="top">Fantastic tones in this shot. I really like the contrast between the golden sand and the purple sky. Your shot is appealing and most worthy of this challenge. Congrats on a wonderful capture! 10 from me.</td>', 'Fantastic tones in this shot. I really like the contrast between the golden sand and the purple sky. Your shot is appealing and most worthy of this challenge. Congrats on a wonderful capture! 10 from me.', '2005-12-02 08:13:03.000000', NULL, 1),
(1915483, 263536, 39349, '<td valign="top">Awesome leading lines that draw you into this shot. I love the conflict between dark and light, symbolizing man''s industrial conflict with nature. Your choice to photograph alternative energy sources adds to this shot by suggesting a more environmentally sound solution to our needs. WHEW! That was a mouthful! Great job and congratulations on a beautiful capture. 10 from me.</td>', 'Awesome leading lines that draw you into this shot. I love the conflict between dark and light, symbolizing man''s industrial conflict with nature. Your choice to photograph alternative energy sources adds to this shot by suggesting a more environmentally sound solution to our needs. WHEW! That was a mouthful! Great job and congratulations on a beautiful capture. 10 from me.', '2005-12-02 08:18:45.000000', NULL, 1),
(1915495, 263532, 18073, '<td valign="top">Nice composition, although personally I would have cropped the unsharp area of the foreground out.  Great light and great setting, I like how out of place the factory looks against the great landscape.  Good work!</td>', 'Nice composition, although personally I would have cropped the unsharp area of the foreground out.  Great light and great setting, I like how out of place the factory looks against the great landscape.  Good work!', '2005-12-02 08:35:08.000000', NULL, 1),
(1915502, 262957, 30881, '<td valign="top">Very nice b&amp;w. Nice to see something besides a factory lit up at night Good job</td>', 'Very nice b&w. Nice to see something besides a factory lit up at night Good job', '2005-12-02 08:43:06.000000', NULL, 1),
(1915503, 263519, 30881, '<td valign="top">Bit too blurry and too much light glare. Excellent idea for subject matter though Good luck</td>', 'Bit too blurry and too much light glare. Excellent idea for subject matter though Good luck', '2005-12-02 08:44:17.000000', NULL, 1),
(1915506, 262623, 30881, '<td valign="top">Nice idea. A bit sharper perhaps? I like all the vertical lines</td>', 'Nice idea. A bit sharper perhaps? I like all the vertical lines', '2005-12-02 08:46:23.000000', NULL, 1),
(1915507, 263243, 30881, '<td valign="top">A bit blurry and lighting needs some help. Great idea for subject matter though</td>', 'A bit blurry and lighting needs some help. Great idea for subject matter though', '2005-12-02 08:47:59.000000', NULL, 1),
(1915510, 263603, 30881, '<td valign="top">The lights are excellent. You''re up against some tough competion as far as night factories go though. Good luck</td>', 'The lights are excellent. You''re up against some tough competion as far as night factories go though. Good luck', '2005-12-02 08:49:23.000000', NULL, 1),
(1915511, 262971, 30881, '<td valign="top">This whole image looks out of focus, including the clouds. Great idea and like the angle this was shot at. Good luck.</td>', 'This whole image looks out of focus, including the clouds. Great idea and like the angle this was shot at. Good luck.', '2005-12-02 08:50:41.000000', NULL, 1),
(1915515, 261490, 30881, '<td valign="top">Great background lighting and a good idea. I think there is just too much for the average human eye to focus on . Lines going in all directions and taking the eye to nowhere. <br/>Good luck</td>', 'Great background lighting and a good idea. I think there is just too much for the average human eye to focus on . Lines going in all directions and taking the eye to nowhere. Good luck', '2005-12-02 08:54:59.000000', NULL, 1),
(1915521, 262079, 30881, '<td valign="top">Very nice layout good subject choicea bit too blurred on right side(caused by smog?)<br/>Most voters as of late seem to like ("bright and shiny".) This may be a bit too drab for there liking. Good luck!</td>', 'Very nice layout good subject choicea bit too blurred on right side(caused by smog?)Most voters as of late seem to like ("bright and shiny".) This may be a bit too drab for there liking. Good luck!', '2005-12-02 08:57:59.000000', NULL, 1),
(1915530, 262836, 30881, '<td valign="top">Very good B&amp;W I think it could have been shot a bit closer and crop bottom foreground. It is doing nothing to enhance the main subject, which is the top of chimneys and steam?smoke.<br/>Due to the brightness of sky and light on steam that is where the eye is directed Black blurry areas do not attract the eye-therefore the bottom area is not important to this image. Good clean.</td>', 'Very good B&W I think it could have been shot a bit closer and crop bottom foreground. It is doing nothing to enhance the main subject, which is the top of chimneys and steam?smoke.Due to the brightness of sky and light on steam that is where the eye is directed Black blurry areas do not attract the eye-therefore the bottom area is not important to this image. Good clean.', '2005-12-02 09:03:33.000000', NULL, 1),
(1915537, 263565, 30881, '<td valign="top">Great idea however I think the bolt would have needs to be as sharp as the nut. Nice reflection off nut. Good luck</td>', 'Great idea however I think the bolt would have needs to be as sharp as the nut. Nice reflection off nut. Good luck', '2005-12-02 09:06:35.000000', NULL, 1),
(1915545, 263031, 30881, '<td valign="top">Normally an image like this would be too cluttered, however because they all direct the eye back towards the centre of photo it works very well. Good capture and good luck</td>', 'Normally an image like this would be too cluttered, however because they all direct the eye back towards the centre of photo it works very well. Good capture and good luck', '2005-12-02 09:08:27.000000', NULL, 1),
(1915552, 263537, 30881, '<td valign="top">Nice subject choice, and I really like the lighting effect. Unfortunately the blurred steel piece in background really distracts from main image. (bad lighting, blurry) Perhaps one solid color across background? Good luck</td>', 'Nice subject choice, and I really like the lighting effect. Unfortunately the blurred steel piece in background really distracts from main image. (bad lighting, blurry) Perhaps one solid color across background? Good luck', '2005-12-02 09:12:57.000000', NULL, 1),
(1915561, 262071, 39349, '<td valign="top">Awesome. I like the symmetrical shape of this shot. A unique approach to this challenge and a well done photograph. I especially like the hint of blue set against the orange and yellow tones. Well done!</td>', 'Awesome. I like the symmetrical shape of this shot. A unique approach to this challenge and a well done photograph. I especially like the hint of blue set against the orange and yellow tones. Well done!', '2005-12-02 09:14:31.000000', NULL, 1),
(1915565, 262036, 30881, '<td valign="top">Like the subject choice the contrast is great, would have liked to see a darker sepia tone though  Good luck, overall its a good image</td>', 'Like the subject choice the contrast is great, would have liked to see a darker sepia tone though  Good luck, overall its a good image', '2005-12-02 09:15:22.000000', NULL, 1),
(1915590, 263070, 30881, '<td valign="top">Great B&amp;W Clean sharp well layed out. Unfortunately nothing of much interest to hold viewers interest. Good phot though "7"</td>', 'Great B&W Clean sharp well layed out. Unfortunately nothing of much interest to hold viewers interest. Good phot though "7"', '2005-12-02 09:21:08.000000', NULL, 1),
(1915612, 263726, 30881, '<td valign="top">Lots of lights and good idea capturing towers with red lights. Compared to competion a bit too blurry. Shooting lights at night is difficult and with a bit of practice it will improve. Good luck</td>', 'Lots of lights and good idea capturing towers with red lights. Compared to competion a bit too blurry. Shooting lights at night is difficult and with a bit of practice it will improve. Good luck', '2005-12-02 09:25:31.000000', NULL, 1),
(1915624, 262118, 30881, '<td valign="top">Well Done! The distorted muck in front of train is excellent. Adds a sort of grungy feel and yet the lighting on part of train makes it look almost look plastiy Very nice indeed "9"</td>', 'Well Done! The distorted muck in front of train is excellent. Adds a sort of grungy feel and yet the lighting on part of train makes it look almost look plastiy Very nice indeed "9"', '2005-12-02 09:28:59.000000', NULL, 1),
(1915634, 263367, 30881, '<td valign="top">Wonderful sunset (background)  Even smooth eye flow.  Overall, very well done!! "9"</td>', 'Wonderful sunset (background)  Even smooth eye flow.  Overall, very well done!! "9"', '2005-12-02 09:31:40.000000', NULL, 1),
(1915638, 261958, 42638, '<td valign="top">Nicely done. Love the almost green glow. Good clear night shot.</td>', 'Nicely done. Love the almost green glow. Good clear night shot.', '2005-12-02 09:32:16.000000', NULL, 1),
(1915642, 263735, 42638, '<td valign="top">Nice picture, Love his expression and the clarity of his face. Good use of space and shadows.</td>', 'Nice picture, Love his expression and the clarity of his face. Good use of space and shadows.', '2005-12-02 09:33:24.000000', NULL, 1),
(1915646, 263328, 42638, '<td valign="top">Nice picture. Love the lights and steam. The leading train tracks make great lines.</td>', 'Nice picture. Love the lights and steam. The leading train tracks make great lines.', '2005-12-02 09:34:15.000000', NULL, 1),
(1915648, 263596, 42638, '<td valign="top">Nice picture. Love the perspective and the symetry of these. Good job.</td>', 'Nice picture. Love the perspective and the symetry of these. Good job.', '2005-12-02 09:34:59.000000', NULL, 1),
(1915651, 263565, 42638, '<td valign="top">Nice interpretation, too bad the bolt is out of focus. Good reflections and nice choice of color.</td>', 'Nice interpretation, too bad the bolt is out of focus. Good reflections and nice choice of color.', '2005-12-02 09:35:54.000000', NULL, 1),
(1915654, 262861, 42638, '<td valign="top">Very cute. Nice interpretation.</td>', 'Very cute. Nice interpretation.', '2005-12-02 09:36:30.000000', NULL, 1),
(1915657, 262063, 42638, '<td valign="top">Nice picture, love the wood building but the other seems a bit blown. Good reflection.</td>', 'Nice picture, love the wood building but the other seems a bit blown. Good reflection.', '2005-12-02 09:37:13.000000', NULL, 1),
(1915658, 263650, 42638, '<td valign="top">Very nice. Good focus and composition. Perfect title.</td>', 'Very nice. Good focus and composition. Perfect title.', '2005-12-02 09:37:50.000000', NULL, 1),
(1915660, 262000, 30881, '<td valign="top">Nice lighting. Shooting a bit closer and slightly sharper would have greatly improved the shot. Good eyeflow on top of building</td>', 'Nice lighting. Shooting a bit closer and slightly sharper would have greatly improved the shot. Good eyeflow on top of building', '2005-12-02 09:38:01.000000', NULL, 1),
(1915663, 261571, 42638, '<td valign="top">Nice detail. I bet it wasn''t easy to get this without overexposing. Good Job!</td>', 'Nice detail. I bet it wasn''t easy to get this without overexposing. Good Job!', '2005-12-02 09:38:51.000000', NULL, 1),
(1915666, 263031, 42638, '<td valign="top">Excellent pictrure, Wonderful Title. It gives it an eerie feeling.</td>', 'Excellent pictrure, Wonderful Title. It gives it an eerie feeling.', '2005-12-02 09:39:51.000000', NULL, 1),
(1915667, 262511, 42638, '<td valign="top">Wow, spectacular colors! Love the silos there, really ties into your title perfectly.</td>', 'Wow, spectacular colors! Love the silos there, really ties into your title perfectly.', '2005-12-02 09:40:40.000000', NULL, 1),
(1915678, 262976, 30881, '<td valign="top">Using challenge theme as background and focusing on grass is an excellent idea, and works great here. Very well done. Grass is sharp clear and helps direct eye into corner of building. My favourite so far.</td>', 'Using challenge theme as background and focusing on grass is an excellent idea, and works great here. Very well done. Grass is sharp clear and helps direct eye into corner of building. My favourite so far.', '2005-12-02 09:43:31.000000', NULL, 1),
(1915684, 261763, 48951, '<td valign="top">This a wonderfull picture. I just love the bright colours.10</td>', 'This a wonderfull picture. I just love the bright colours.10', '2005-12-02 09:45:24.000000', NULL, 1),
(1915687, 262543, 48951, '<td valign="top">The lights are amazing. WOW. 10</td>', 'The lights are amazing. WOW. 10', '2005-12-02 09:46:33.000000', NULL, 1),
(1915692, 263154, 30881, '<td valign="top">Rarely does an image like this make it close to the ribbon area, Poor lighting, poor focus, and poor subject choice.  Perhaps browse through challeng archives and see what has won in the past. May get the imagination working in a more positive direction.</td>', 'Rarely does an image like this make it close to the ribbon area, Poor lighting, poor focus, and poor subject choice.  Perhaps browse through challeng archives and see what has won in the past. May get the imagination working in a more positive direction.', '2005-12-02 09:48:38.000000', NULL, 1),
(1915699, 262953, 48951, '<td valign="top">This photo is perfect for a industria challenge.10l</td>', 'This photo is perfect for a industria challenge.10l', '2005-12-02 09:50:40.000000', NULL, 1),
(1915703, 261958, 30881, '<td valign="top">Great! Nice color from lights. Good shadow contrast  Steamy clouds in backbground works well.  Very nice layout. Overall, excellent!!  "10"</td>', 'Great! Nice color from lights. Good shadow contrast  Steamy clouds in backbground works well.  Very nice layout. Overall, excellent!!  "10"', '2005-12-02 09:52:08.000000', NULL, 1),
(1915711, 263716, 30881, '<td valign="top">Lighting and grainy feel adds a nice surrealistic feel to this. Wish it was presented in a larger format. Overall very well done. Good camera positionaing by the way.</td>', 'Lighting and grainy feel adds a nice surrealistic feel to this. Wish it was presented in a larger format. Overall very well done. Good camera positionaing by the way.', '2005-12-02 10:01:50.000000', NULL, 1),
