(1916582, 262251, 42456, '<td valign="top">Where are the Safety Goggles?! LOL!</td>', 'Where are the Safety Goggles?! LOL!', '2005-12-02 15:32:42.000000', NULL, 1),
(1916616, 263735, 44963, '<td valign="top">This is a significantly good shot.  Standing out from the crowd in this challenge.  The lighting and the angle you took the picture from create an image that made me stop.  One of the things I like about voting is that you get to know what you like in a photograph.  You have certainly done it for me with this one.  Thanks</td>', 'This is a significantly good shot.  Standing out from the crowd in this challenge.  The lighting and the angle you took the picture from create an image that made me stop.  One of the things I like about voting is that you get to know what you like in a photograph.  You have certainly done it for me with this one.  Thanks', '2005-12-02 15:45:56.000000', NULL, 1),
(1916632, 263538, 44963, '<td valign="top">There were a lot or very boring smoke-stacks in this challenge - yours was not one of them.  It created feelings of sinister things going on.  Of a dark moody place.  I''m sure lots of great people work here but I liked this picture because of the "lord of the rings" type emotions is created with me.  Very good shot.  Thanks</td>', 'There were a lot or very boring smoke-stacks in this challenge - yours was not one of them.  It created feelings of sinister things going on.  Of a dark moody place.  I''m sure lots of great people work here but I liked this picture because of the "lord of the rings" type emotions is created with me.  Very good shot.  Thanks', '2005-12-02 15:49:56.000000', NULL, 1),
(1916673, 262034, 44963, '<td valign="top">A very classy shot.  A bit of fresh air in all the billowing smoke-stacks of this challenge.  I like the B&amp;W approch - spot on for this shot.  The signage in the background creates the story for me.  Your image stopped my flicking through the challenge entries and drew me in.  Thanks</td>', 'A very classy shot.  A bit of fresh air in all the billowing smoke-stacks of this challenge.  I like the B&W approch - spot on for this shot.  The signage in the background creates the story for me.  Your image stopped my flicking through the challenge entries and drew me in.  Thanks', '2005-12-02 15:59:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1916684, 262957, 44963, '<td valign="top">Images in this challenge have lacked people as subjects.  We seem to have forgotten that all the big machinery, all the big factories and everything else need people to make them work.  Your image stuck a much better balance.</td>', 'Images in this challenge have lacked people as subjects.  We seem to have forgotten that all the big machinery, all the big factories and everything else need people to make them work.  Your image stuck a much better balance.', '2005-12-02 16:02:55.000000', NULL, 1),
(1916723, 263070, 47151, '<td valign="top">I would have found this more appealing if the electrical conduits were not in the picture. A couple of steps forward or a tighter crop on the right hand side to where the coloum acts as frame.</td>', 'I would have found this more appealing if the electrical conduits were not in the picture. A couple of steps forward or a tighter crop on the right hand side to where the coloum acts as frame.', '2005-12-02 16:09:34.000000', NULL, 1),
(1916788, 262377, 48487, '<td valign="top">I think it would be more dramatic if it was darker.  (I happened to get a view of it like that when my laptop screen wasn''t tilted just right.)  Still, a good shot.</td>', 'I think it would be more dramatic if it was darker.  (I happened to get a view of it like that when my laptop screen wasn''t tilted just right.)  Still, a good shot.', '2005-12-02 16:31:17.000000', NULL, 1),
