(1918261, 262984, 32084, '<td valign="top">This is a very nice piece and I am scoring it high.  However, it does feel over-processed - maybe too much USM, not sure but the edges all seem a little different.</td>', 'This is a very nice piece and I am scoring it high.  However, it does feel over-processed - maybe too much USM, not sure but the edges all seem a little different.', '2005-12-03 01:24:16.000000', NULL, 1),
(1918277, 263650, 32084, '<td valign="top">This is nice work.  I wonder if you tried rotating either to correct for the siding being slightly off vertical or goinf the other way and pushing it more toward a 45?  As it is now it seems a little conflicted.  Still a very nice shot.</td>', 'This is nice work.  I wonder if you tried rotating either to correct for the siding being slightly off vertical or goinf the other way and pushing it more toward a 45?  As it is now it seems a little conflicted.  Still a very nice shot.', '2005-12-03 01:30:45.000000', NULL, 1),
(1918314, 263596, 33672, '<td valign="top">great comp, tones and lines.  A contender! Good Luck!</td>', 'great comp, tones and lines.  A contender! Good Luck!', '2005-12-03 02:14:42.000000', NULL, 1),
