(1921793, 263755, 30881, '<td valign="top">Poor lighting, poor sharpness. poor contrast, and poor interpretation of challenge title. Sorry but with the quality of other photographers here I con''t think this is a very serious effort on your part, and its doubtful if this will score very high. Good luck though<br/></td>', 'Poor lighting, poor sharpness. poor contrast, and poor interpretation of challenge title. Sorry but with the quality of other photographers here I con''t think this is a very serious effort on your part, and its doubtful if this will score very high. Good luck though', '2005-12-04 20:05:21.000000', NULL, 1),
(1921801, 262251, 30881, '<td valign="top">I''m sure there are many voters who will vote this one reasonably high. sorry but I just don''t care for this art form or photographic style. Good luck.</td>', 'I''m sure there are many voters who will vote this one reasonably high. sorry but I just don''t care for this art form or photographic style. Good luck.', '2005-12-04 20:10:08.000000', NULL, 1),
(1921809, 263457, 30881, '<td valign="top">This just seems too blurry/hazy. Not nearly sharp enough and seems to have far too much sunlight glaring off buildings. Try a different time of day perhaps?  Good luck.</td>', 'This just seems too blurry/hazy. Not nearly sharp enough and seems to have far too much sunlight glaring off buildings. Try a different time of day perhaps?  Good luck.', '2005-12-04 20:13:18.000000', NULL, 1),
(1921924, 262220, 42808, '<td valign="top">Interesting. From the thumbnail--the rail looked like a pyramid. I like the DOF, but I wish there was something on the more focused area of the rail to enhance interest.</td>', 'Interesting. From the thumbnail--the rail looked like a pyramid. I like the DOF, but I wish there was something on the more focused area of the rail to enhance interest.', '2005-12-04 21:11:42.000000', NULL, 1),
