INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1926710, 262251, 25553, '<td valign="top">i love the clash between beautiful and delicate with rough and industrial..good job</td>', 'i love the clash between beautiful and delicate with rough and industrial..good job', '2005-12-06 08:11:18.000000', NULL, 1),
(1926720, 262984, 25553, '<td valign="top">this is a beautiful picture. a post card i would send my mother from my travels.. although its a little hidden and it seems like a geyser at first it makes total sense when you notive the train. awesome!</td>', 'this is a beautiful picture. a post card i would send my mother from my travels.. although its a little hidden and it seems like a geyser at first it makes total sense when you notive the train. awesome!', '2005-12-06 08:21:04.000000', NULL, 1),
(1927090, 263335, 32644, '<td valign="top">Nice shot - wish it were bigger.</td>', 'Nice shot - wish it were bigger.', '2005-12-06 11:12:11.000000', NULL, 1),
(1927172, 262984, 39679, '<td valign="top">Boy this is a tough one.  I understand how you want to tie it to "industrial" but I''m not 100% convinced.  On the other hand, this is an absolutely fabulous photo.  It''s certainly something I''d hang on my wall.</td>', 'Boy this is a tough one.  I understand how you want to tie it to "industrial" but I''m not 100% convinced.  On the other hand, this is an absolutely fabulous photo.  It''s certainly something I''d hang on my wall.', '2005-12-06 11:59:40.000000', NULL, 1),
(1927180, 262394, 39679, '<td valign="top">This is a really good shot.  I wish you could have de-emphasized the sky though.  In this case it doesn''t add to the image, IMHO.  However, it''s still a good shot.</td>', 'This is a really good shot.  I wish you could have de-emphasized the sky though.  In this case it doesn''t add to the image, IMHO.  However, it''s still a good shot.', '2005-12-06 12:02:10.000000', NULL, 1),
(1927190, 263028, 39679, '<td valign="top">I would normally think this shot lacks impact but the steam plume is a great subject.  Your exposure is bang on which makes the plume very dramatic.  Nicely done.</td>', 'I would normally think this shot lacks impact but the steam plume is a great subject.  Your exposure is bang on which makes the plume very dramatic.  Nicely done.', '2005-12-06 12:06:55.000000', NULL, 1),
(1927193, 263532, 39679, '<td valign="top">Very nice shot.  Your use of depth of field really completes this shot.</td>', 'Very nice shot.  Your use of depth of field really completes this shot.', '2005-12-06 12:11:45.000000', NULL, 1),
(1927369, 262251, 19064, '<td valign="top">Tut tut, no safety glasses! 8</td>', 'Tut tut, no safety glasses! 8', '2005-12-06 13:14:43.000000', NULL, 1),
(1927534, 263362, 39679, '<td valign="top">Man it''s nice to see someone create a monochromatic shot that''s not black and white!</td>', 'Man it''s nice to see someone create a monochromatic shot that''s not black and white!', '2005-12-06 14:11:56.000000', NULL, 1),
(1927586, 263355, 45927, '<td valign="top">I like the detail in this shot-- gives it real industrial character. And an interesting title. Good job. :)</td>', 'I like the detail in this shot-- gives it real industrial character. And an interesting title. Good job. :)', '2005-12-06 14:28:41.000000', NULL, 1),
(1927592, 263446, 45927, '<td valign="top">Very industrial. Love all the lights and smoke. Nice.</td>', 'Very industrial. Love all the lights and smoke. Nice.', '2005-12-06 14:31:13.000000', NULL, 1),
(1927600, 262516, 42100, '<td valign="top">Very nice composition,  the contrast just seems a little flat.</td>', 'Very nice composition,  the contrast just seems a little flat.', '2005-12-06 14:33:19.000000', NULL, 1),
(1927614, 262606, 45927, '<td valign="top">I would''ve liked to see the whole building, and then all the smoke... It''s a little plain without the whole thing that''s why. But otherwise, good idea.</td>', 'I would''ve liked to see the whole building, and then all the smoke... It''s a little plain without the whole thing that''s why. But otherwise, good idea.', '2005-12-06 14:36:50.000000', NULL, 1),
(1927625, 261445, 42100, '<td valign="top">Interesting sky, but the expsoure seems a little too dark on the building.</td>', 'Interesting sky, but the expsoure seems a little too dark on the building.', '2005-12-06 14:38:15.000000', NULL, 1),
(1927629, 263598, 45927, '<td valign="top">This is a nice shot. Shows the bad industrialness take over nature. The only thing I''d suggest is a little less sky... Just too much for me.</td>', 'This is a nice shot. Shows the bad industrialness take over nature. The only thing I''d suggest is a little less sky... Just too much for me.', '2005-12-06 14:38:54.000000', NULL, 1),
(1927632, 262901, 42100, '<td valign="top">There just seems be too much going on here compositionally.</td>', 'There just seems be too much going on here compositionally.', '2005-12-06 14:39:34.000000', NULL, 1),
(1927640, 262118, 45927, '<td valign="top">I really like this picture. It really does convey the power in industries because of it''s towering appearance. Nicely done. :)</td>', 'I really like this picture. It really does convey the power in industries because of it''s towering appearance. Nicely done. :)', '2005-12-06 14:40:20.000000', NULL, 1),
(1927650, 263028, 45927, '<td valign="top">Good capture. Love all the smoke stacks and that big puff of smoke. Very industrial.</td>', 'Good capture. Love all the smoke stacks and that big puff of smoke. Very industrial.', '2005-12-06 14:42:44.000000', NULL, 1),
(1927655, 261915, 42100, '<td valign="top">This is a cool idea, but just seems to busy.   Maybe if you moved closer to the chainlink and blurred it.</td>', 'This is a cool idea, but just seems to busy.   Maybe if you moved closer to the chainlink and blurred it.', '2005-12-06 14:43:46.000000', NULL, 1),
(1927664, 261414, 45927, '<td valign="top">I like the message in this!! Industrial sunsets will replace the natural ones!! O.o Eeep. The only thing I''d say is it does look a tad blurry.</td>', 'I like the message in this!! Industrial sunsets will replace the natural ones!! O.o Eeep. The only thing I''d say is it does look a tad blurry.', '2005-12-06 14:45:50.000000', NULL, 1),
(1927672, 263735, 45927, '<td valign="top">I really like his expresstion. It looks so emotional and real--I love it.</td>', 'I really like his expresstion. It looks so emotional and real--I love it.', '2005-12-06 14:47:14.000000', NULL, 1),
(1927676, 263734, 42100, '<td valign="top">Great sky in this photo.  This almost has a midevil castle feel to it.  Nice job!</td>', 'Great sky in this photo.  This almost has a midevil castle feel to it.  Nice job!', '2005-12-06 14:47:33.000000', NULL, 1),
(1927687, 263501, 42100, '<td valign="top">Great night shot.  Very nicely done!</td>', 'Great night shot.  Very nicely done!', '2005-12-06 14:49:48.000000', NULL, 1),
(1927692, 263064, 45927, '<td valign="top">This picture looks a little blurry... Looks like there''s a little glare on the light, which is a bit distracting.</td>', 'This picture looks a little blurry... Looks like there''s a little glare on the light, which is a bit distracting.', '2005-12-06 14:50:33.000000', NULL, 1),
(1927712, 263565, 45927, '<td valign="top">Interesting message. But I think that both the bolt and nut should be in focus.</td>', 'Interesting message. But I think that both the bolt and nut should be in focus.', '2005-12-06 14:53:17.000000', NULL, 1),
(1927769, 262394, 45925, '<td valign="top">nice shot. this is very nice and captures the moment.</td>', 'nice shot. this is very nice and captures the moment.', '2005-12-06 15:02:05.000000', NULL, 1),
(1927771, 263466, 45925, '<td valign="top">nice shot.. a little bland, but still nice.</td>', 'nice shot.. a little bland, but still nice.', '2005-12-06 15:02:26.000000', NULL, 1),
(1927774, 262432, 45925, '<td valign="top">nice shot. this looks very tarnished and industrial.</td>', 'nice shot. this looks very tarnished and industrial.', '2005-12-06 15:02:43.000000', NULL, 1),
(1927778, 263171, 45925, '<td valign="top">nice shot. the blue backround with the yellow machine, looks very nice and really makes the yellow cat machine pop.</td>', 'nice shot. the blue backround with the yellow machine, looks very nice and really makes the yellow cat machine pop.', '2005-12-06 15:03:17.000000', NULL, 1),
(1927783, 263478, 45925, '<td valign="top">nice shot. the lines in this photo are beautiful.</td>', 'nice shot. the lines in this photo are beautiful.', '2005-12-06 15:03:58.000000', NULL, 1),
(1927786, 263565, 45925, '<td valign="top">nice shot.  i love the blue light.</td>', 'nice shot.  i love the blue light.', '2005-12-06 15:04:13.000000', NULL, 1),
(1927806, 263362, 27556, '<td valign="top">Beautiful!!!!!</td>', 'Beautiful!!!!!', '2005-12-06 15:11:06.000000', NULL, 1),
(1927813, 262251, 27556, '<td valign="top">although its a lovely image i dont think nudity was nesicary in this shot, but thats just my oppinion</td>', 'although its a lovely image i dont think nudity was nesicary in this shot, but thats just my oppinion', '2005-12-06 15:15:02.000000', NULL, 1),
(1927941, 262953, 48717, '<td valign="top">If this picure of the plant were taken in front of the power lines, it would have turned out so much nicer.  If you could not manage to get infront of them, then a tighter zoom on the plant itself would give the same effect by eliminating the power lines from the pic.</td>', 'If this picure of the plant were taken in front of the power lines, it would have turned out so much nicer.  If you could not manage to get infront of them, then a tighter zoom on the plant itself would give the same effect by eliminating the power lines from the pic.', '2005-12-06 15:57:19.000000', NULL, 1),
(1927963, 262540, 48717, '<td valign="top">Lighting is good,  but if you were really just trying to highlight the pulley, then I would say zoom and swivel a bit in order to get just the front of pulley and chains in sharp focus.  Use a DOF that would blur the rest of the machinery which is a bit distracting.</td>', 'Lighting is good,  but if you were really just trying to highlight the pulley, then I would say zoom and swivel a bit in order to get just the front of pulley and chains in sharp focus.  Use a DOF that would blur the rest of the machinery which is a bit distracting.', '2005-12-06 16:05:51.000000', NULL, 1),
(1927974, 261824, 48717, '<td valign="top">This has a lot of potential, but it is missing something.  Perhaps the contrast is too low.  For a different perspective place the camera on the rail and take the pic, or even better, try the pic right after a train has passed.</td>', 'This has a lot of potential, but it is missing something.  Perhaps the contrast is too low.  For a different perspective place the camera on the rail and take the pic, or even better, try the pic right after a train has passed.', '2005-12-06 16:13:30.000000', NULL, 1),
(1927988, 262901, 48717, '<td valign="top">This is a bit too dark for me to see what is going on.  I think it is a train in motion, but seems there is a building that is blurred also.  If you did not use one, you should try a tripod, or at least make sure the camera is on a stable surface for the longer exposure times.  A subject that has lights, i.e. cars, or at least lights nearby might work better.  The glow from these would help to illuminate your subject.</td>', 'This is a bit too dark for me to see what is going on.  I think it is a train in motion, but seems there is a building that is blurred also.  If you did not use one, you should try a tripod, or at least make sure the camera is on a stable surface for the longer exposure times.  A subject that has lights, i.e. cars, or at least lights nearby might work better.  The glow from these would help to illuminate your subject.', '2005-12-06 16:20:21.000000', NULL, 1),
(1927992, 262222, 48717, '<td valign="top">This is nice, but if it were in sharp focus it would be a lot nicer.  Tighter zoom/crop might help also.  I love the deep blue sky.</td>', 'This is nice, but if it were in sharp focus it would be a lot nicer.  Tighter zoom/crop might help also.  I love the deep blue sky.', '2005-12-06 16:22:46.000000', NULL, 1),
(1928001, 261445, 48717, '<td valign="top">Nice picture, a bit dark though.  I would shift it over a bit to get, less of the white  building, and all of the other crane instead.</td>', 'Nice picture, a bit dark though.  I would shift it over a bit to get, less of the white  building, and all of the other crane instead.', '2005-12-06 16:27:21.000000', NULL, 1),
(1928008, 262355, 48786, '<td valign="top">Good photo, and very sexy, but unfortunately nothing to do with industry...</td>', 'Good photo, and very sexy, but unfortunately nothing to do with industry...', '2005-12-06 16:31:27.000000', NULL, 1),
(1928076, 262901, 24642, '<td valign="top">I like the mood here.   Powerlines, trucks, pollution and speed.  The title fits well.</td>', 'I like the mood here.   Powerlines, trucks, pollution and speed.  The title fits well.', '2005-12-06 16:58:50.000000', NULL, 1),
(1928088, 261420, 24642, '<td valign="top">Original take on the challenge.  Good perspective and post processing.</td>', 'Original take on the challenge.  Good perspective and post processing.', '2005-12-06 17:00:44.000000', NULL, 1),
(1928091, 263736, 24642, '<td valign="top">Very massive.  Great colors.</td>', 'Very massive.  Great colors.', '2005-12-06 17:01:54.000000', NULL, 1),
(1928098, 262221, 24642, '<td valign="top">Good title.  The frame feels a bit too heavy.</td>', 'Good title.  The frame feels a bit too heavy.', '2005-12-06 17:04:06.000000', NULL, 1),
(1928108, 262991, 24642, '<td valign="top">This seems overexposed.  The brightest parts have lost all detail.</td>', 'This seems overexposed.  The brightest parts have lost all detail.', '2005-12-06 17:06:38.000000', NULL, 1),
